#!/bin/sh
# Runs once, on first start of an empty data volume (docker-entrypoint-initdb.d). Pre-creates the
# roles that migrations 0001 and 0008 would otherwise create with fixed dev-only passwords. The
# passwords come from the container environment (generated by bootstrap.sh), never from a file here.
set -eu
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" \
  -v owner_pw="$LOCKSMITH_OWNER_PASSWORD" \
  -v app_pw="$LOCKSMITH_APP_PASSWORD" \
  -v verifier_pw="$LOCKSMITH_AUDIT_VERIFIER_PASSWORD" >/dev/null <<'SQL'
CREATE ROLE locksmith_owner LOGIN PASSWORD :'owner_pw' NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
CREATE ROLE locksmith_app LOGIN PASSWORD :'app_pw' NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
CREATE ROLE audit_verifier LOGIN PASSWORD :'verifier_pw' NOSUPERUSER BYPASSRLS NOCREATEDB NOCREATEROLE;
SQL
echo "postgres-init: locksmith roles created"
